mapper.select:
SELECT id, row_version, created_at, updated_at, sequence_id, order_index, narrative_purpose, retention_role, subjects_json::text AS subjects_json, location_ref, start_state_json::text AS start_state_json, action_json::text AS action_json, end_state_json::text AS end_state_json, composition_json::text AS composition_json, camera_json::text AS camera_json, subject_motion_json::text AS subject_motion_json, camera_motion_json::text AS camera_motion_json, environment_motion_json::text AS environment_motion_json, target_duration_ms, generation_strategy, quality_profile, continuity_from_shot_id, continuity_to_shot_id, status FROM shots WHERE sequence_id IN
#{id}
ORDER BY sequence_id ASC, order_index ASC, id ASC
